package com.cinenest.access.internal;
import java.util.*;import java.time.Instant;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository
class JdbcAccessRepository implements AccessRepository {
 public Optional<Map<String,Object>> bookingWork(UUID credential){return jdbc.sql("SELECT credential_id,credential_version,state,operation_id FROM cinenest_access.access_work WHERE credential_id=:id FOR UPDATE").param("id",credential).query().listOfRows().stream().findFirst();}
 public List<Map<String,Object>> bookingCredentials(UUID booking){return jdbc.sql("SELECT credential_id,booking_id,booking_revision,owner_id,venue_id,room_id,starts_at,ends_at,timezone,version,revision,state FROM cinenest_access.access_credential WHERE booking_id=:id ORDER BY version DESC FOR UPDATE").param("id",booking).query().listOfRows();}
 private final JdbcClient jdbc;JdbcAccessRepository(JdbcClient jdbc){this.jdbc=jdbc;}
 public UUID bookingFor(UUID id){return jdbc.sql("SELECT booking_id FROM cinenest_access.access_credential WHERE credential_id=:id").param("id",id).query(UUID.class).optional().orElseThrow(()->new AccessFailure(404));}
 public List<Map<String,Object>> history(UUID id){return jdbc.sql("SELECT event_id AS id,actor_id AS actor,action,outcome,created_at AS at FROM cinenest_access.access_audit WHERE credential_id=:id ORDER BY created_at,event_id LIMIT 100").param("id",id).query().listOfRows();}
 public List<UUID> cleanupCandidates(){return jdbc.sql("SELECT credential_id FROM cinenest_access.access_credential WHERE (protected_secret IS NOT NULL AND retain_until<=clock_timestamp()) OR (state IN('SCHEDULED','ACTIVE') AND ends_at<=clock_timestamp()) ORDER BY credential_id LIMIT 100").query(UUID.class).list();}
 public Instant now(){return jdbc.sql("SELECT clock_timestamp()").query(java.time.OffsetDateTime.class).single().toInstant();}
 public void lock(UUID booking){jdbc.sql("SELECT pg_advisory_xact_lock(hashtextextended(:id,13001))").param("id",booking.toString()).query().listOfRows();}
 public Optional<Map<String,Object>> credential(UUID id){return jdbc.sql("SELECT * FROM cinenest_access.access_credential WHERE credential_id=:id FOR UPDATE").param("id",id).query().listOfRows().stream().findFirst();}
 public Optional<Map<String,Object>> latest(UUID booking){return jdbc.sql("SELECT * FROM cinenest_access.access_credential WHERE booking_id=:id ORDER BY version DESC LIMIT 1 FOR UPDATE").param("id",booking).query().listOfRows().stream().findFirst();}
 public Map<String,Object> work(UUID id){return jdbc.sql("SELECT * FROM cinenest_access.access_work WHERE credential_id=:id FOR UPDATE").param("id",id).query().singleRow();}
 public void create(Map<String,Object> r){jdbc.sql("INSERT INTO cinenest_access.access_credential(credential_id,booking_id,booking_revision,owner_id,venue_id,room_id,starts_at,ends_at,timezone,version,revision,state,token_hash,protected_secret,key_version,retain_until) VALUES(:credential_id,:booking_id,:booking_revision,:owner_id,:venue_id,:room_id,:starts_at,:ends_at,:timezone,:version,0,'SCHEDULED',:token_hash,:protected_secret,:key_version,:retain_until)").params(r).update();jdbc.sql("INSERT INTO cinenest_access.access_work(operation_id,credential_id,credential_version,state) VALUES(:op,:id,:version,'PENDING_SIMULATION')").param("op",UUID.randomUUID()).param("id",r.get("credential_id")).param("version",r.get("version")).update();}
 public void save(Map<String,Object> r){jdbc.sql("UPDATE cinenest_access.access_credential SET state=:state,revision=revision+1,protected_secret=:protected_secret,disclosed_at=:disclosed_at WHERE credential_id=:credential_id AND revision=:revision").params(r).update();r.put("revision",((Number)r.get("revision")).longValue()+1);}
 public void workState(UUID id,String state,boolean installed,boolean increment){jdbc.sql("UPDATE cinenest_access.access_work SET state=:s,attempts=attempts+:n,evidence_operation=CASE WHEN :yes THEN operation_id ELSE NULL END,evidence_version=CASE WHEN :yes THEN credential_version ELSE NULL END,updated_at=clock_timestamp() WHERE credential_id=:id").param("s",state).param("n",increment?1:0).param("yes",installed).param("id",id).update();}
 public void audit(UUID actor,UUID credential,UUID booking,UUID venue,String action,String outcome){jdbc.sql("INSERT INTO cinenest_access.access_audit(event_id,actor_id,credential_id,booking_id,venue_id,action,outcome) VALUES(:e,:a,:c,:b,:v,:action,:outcome)").param("e",UUID.randomUUID()).param("a",actor).param("c",credential).param("b",booking).param("v",venue).param("action",action).param("outcome",outcome).update();}
 public int rate(UUID actor,int seconds){return jdbc.sql("SELECT count(*) FROM cinenest_access.access_audit WHERE actor_id=:a AND created_at>clock_timestamp()-:s*INTERVAL '1 second'").param("a",actor).param("s",seconds).query(Integer.class).single();}
 public int attempts(UUID id){return jdbc.sql("SELECT count(*) FROM cinenest_access.access_attempt WHERE credential_id=:id").param("id",id).query(Integer.class).single();}
 public int disclosures(UUID id){return jdbc.sql("SELECT count(*) FROM cinenest_access.access_audit WHERE credential_id=:id AND action='REVEAL' AND outcome='ALLOW'").param("id",id).query(Integer.class).single();}
 public Optional<Map<String,Object>> command(UUID actor,UUID key){return jdbc.sql("SELECT * FROM cinenest_access.access_command WHERE actor_id=:a AND command_key=:k").param("a",actor).param("k",key).query().listOfRows().stream().findFirst();}
 public void command(UUID actor,UUID key,UUID booking,UUID credential,String kind,String hash){jdbc.sql("INSERT INTO cinenest_access.access_command(actor_id,command_key,booking_id,credential_id,kind,payload_hash) VALUES(:a,:k,:b,:c,:kind,:hash)").param("a",actor).param("k",key).param("b",booking).param("c",credential).param("kind",kind).param("hash",hash).update();}
 public void attempt(UUID actor,UUID id,boolean success){jdbc.sql("INSERT INTO cinenest_access.access_attempt VALUES(:id,:c,:a,:o,clock_timestamp())").param("id",UUID.randomUUID()).param("c",id).param("a",actor).param("o",success?"SIMULATED_ENTRY":"DENIED").update();}
 public List<UUID> ids(UUID venue,int page,int size){return jdbc.sql("SELECT credential_id FROM cinenest_access.access_credential WHERE venue_id=:v ORDER BY created_at DESC,credential_id LIMIT :s OFFSET :o").param("v",venue).param("s",size).param("o",page*size).query(UUID.class).list();}
}
